  total: { qtd: 860, valor: 1042017.76, label: "Total Inventariado" },
  critica: { qtd: 72, valor: 10131.92, label: "Idade Crítica (>15 anos)", bg: "#fef2f2", color: "#dc2626", border: "#fca5a5", icon: "🚨" },
